<script setup lang="ts">
import type { ConsumerReport } from '../composables/useConsumer'
import { formatDisplayDate } from '../utils/formatDisplayDate'
definePageMeta({layout:'consumer'})
const { profileId, profiles, request, requireSession } = useConsumer()
const reports=ref<ConsumerReport[]>([]), loading=ref(true), error=ref('')
useHead({title:'Home | Doclyzer'})
async function load(){ const id=profileId.value;reports.value=[];loading.value=true;error.value='';if(!id){loading.value=false;return}try{const data=await request<{reports:ConsumerReport[]}>(`/reports?profileId=${encodeURIComponent(id)}`);if(id===profileId.value)reports.value=data.reports}catch(cause){error.value=(cause as Error).message}finally{loading.value=false}}
onMounted(async()=>{try{if(await requireSession())await load()}catch(cause){error.value=(cause as Error).message;loading.value=false}})
watch(profileId,()=>void load())
const latest=computed(()=>reports.value[0]);const attention=computed(()=>reports.value.filter(r=>['failed','needs_attention','processing'].includes(r.processingState??'')))
</script>
<template><div><header class="page-heading"><div><p class="eyebrow">{{ profiles.find(p=>p.id===profileId)?.name ?? 'Your space' }}</p><h1>Your results, in one place</h1><p class="muted">Check what is ready and continue reviewing your reports.</p></div><NuxtLink class="button" to="/reports/upload">Add report</NuxtLink></header><p v-if="error" role="alert" class="alert error">{{ error }} <button class="secondary" @click="load">Retry</button></p><p v-if="loading" role="status">Loading your reports…</p><div v-else-if="!profiles.length" class="empty"><h2>Start with a profile</h2><p>Add yourself or a family member before uploading a report.</p><NuxtLink class="button" to="/you">Add profile</NuxtLink></div><div v-else-if="!reports.length" class="empty"><h2>No reports yet</h2><p>Add a lab report and we’ll show its results here when processing finishes.</p><NuxtLink class="button" to="/reports/upload">Add report</NuxtLink></div><template v-else><section v-if="attention.length" class="card"><h2>Needs your attention</h2><p>{{ attention.length }} report{{ attention.length===1?'':'s' }} processing or needing review.</p><NuxtLink to="/reports">See reports</NuxtLink></section><section class="card"><p class="eyebrow">Latest report</p><h2>{{ latest?.originalFileName }}</h2><p class="muted">{{ latest?.collectionDate ? `Collected ${formatDisplayDate(latest.collectionDate)}` : 'Collection date unknown' }}</p><p>{{ (latest?.processingState??latest?.status)?.replaceAll('_',' ') }}</p><NuxtLink v-if="latest" class="button" :to="`/reports/${latest.id}`">View report</NuxtLink></section><div class="grid"><NuxtLink class="card" to="/reports"><h2>Report history</h2><p>Find every report for this profile.</p></NuxtLink><NuxtLink class="card" to="/trends"><h2>Trends</h2><p>See comparable results over time.</p></NuxtLink></div></template></div></template>
